    CREATE TABLE #ExampleThroughputExpected([RowFlowOrdinal] bigint NOT NULL, [ExecutionId] uniqueidentifier NOT NULL, [SourceId] uniqueidentifier NOT NULL, [SourceName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [OccurrenceStartLogId] int NOT NULL, [OccurrenceEndLogId] int NOT NULL, [PathId] int NOT NULL, [PathName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [DestinationComponentId] int NOT NULL, [DestinationComponentName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [InputId] int NOT NULL, [InputName] nvarchar(4000) COLLATE SQL_Latin1_General_CP1_CS_AS NULL, [EventCount] bigint NOT NULL, [RowsSentSum] decimal(38,0) NOT NULL, [MinRowsSent] bigint NOT NULL, [MaxRowsSent] bigint NOT NULL, [FirstObservedTime] datetime NOT NULL, [LastObservedTime] datetime NOT NULL, [EvidenceLogIdsJson] nvarchar(max) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [SourceNameConflict] bit NOT NULL, [PathNameConflict] bit NOT NULL, [DestinationNameConflict] bit NOT NULL, [InputNameConflict] bit NOT NULL, [InputIsTruncated] bit NOT NULL, [CoverageStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [OccurrenceStartTime] datetime NULL, [OccurrenceEndTime] datetime NULL, [ObservedExecutionDurationMs] bigint NULL, [ReportedTransferRowsPerSecond] decimal(38,6) NULL, [RateStatus] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [RateTimeBasis] varchar(40) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [EvidenceLevel] varchar(32) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL, [EvidenceSource] nvarchar(160) COLLATE SQL_Latin1_General_CP1_CS_AS NOT NULL);
    SELECT TOP(0) * INTO #ExampleThroughputActual FROM #ExampleThroughputExpected;
    DECLARE @Case int=1,@Label varchar(40),@Rows varchar(30),@Duration int,@Kind varchar(40),@Cap int,@Expected nvarchar(max),@Flow nvarchar(2048),@Through bit;
    WHILE @Case<=24
    BEGIN
        SELECT @Label=Label,@Rows=RowsText,@Duration=DurationMs,@Kind=Kind,@Cap=Cap,@Expected=ExpectedJson FROM @Cases WHERE CaseId=@Case;
        SET @Flow=N'Rows were provided to a data flow component as input. : : 1 : ExamplePath : 2 : ExampleDestination : 3 : ExampleInput : '+CONVERT(nvarchar(30),@Rows);
        DELETE dbo.ExampleThroughputLogSource;
        INSERT dbo.ExampleThroughputLogSource VALUES(10,N'OnPreExecute',N'ExampleFlow',@Source,@Id,@T,@T,0,N''),
            (20,N'OnPipelineRowsSent',N'ExampleFlow',@Source,@Id,@T,@T,0,@Flow),
            (30,N'OnPostExecute',N'ExampleFlow',@Source,@Id,DATEADD(millisecond,@Duration,@T),DATEADD(millisecond,@Duration,@T),0,N'');
        IF @Kind='SUM' INSERT dbo.ExampleThroughputLogSource SELECT 21,event,source,sourceid,executionid,starttime,endtime,datacode,message FROM dbo.ExampleThroughputLogSource WHERE id=20;
        IF @Kind='NO_END' DELETE dbo.ExampleThroughputLogSource WHERE id=30;
        IF @Kind='NO_START' DELETE dbo.ExampleThroughputLogSource WHERE id=10;
        IF @Kind='NULL_TIME' UPDATE dbo.ExampleThroughputLogSource SET starttime=NULL WHERE id=20;
        IF @Kind='NULL_SOURCE' UPDATE dbo.ExampleThroughputLogSource SET sourceid=NULL WHERE id=20;
        IF @Kind='BAD_PAYLOAD' UPDATE dbo.ExampleThroughputLogSource SET message=N'unknown' WHERE id=20;
        IF @Kind='BAD_SIBLING' INSERT dbo.ExampleThroughputLogSource VALUES(21,N'OnPipelineRowsSent',N'ExampleFlow',@Source,@Id,@T,@T,0,N'unknown');
        IF @Kind='NAME_CONFLICT' INSERT dbo.ExampleThroughputLogSource VALUES(21,N'OnPipelineRowsSent',N'ExampleFlow',@Source,@Id,@T,@T,0,REPLACE(@Flow,N'ExamplePath',N'ExampleOtherPath'));
        IF @Kind='REPEAT' INSERT dbo.ExampleThroughputLogSource VALUES(40,N'OnPreExecute',N'ExampleFlow',@Source,@Id,DATEADD(second,3,@T),DATEADD(second,3,@T),0,N''),
            (50,N'OnPipelineRowsSent',N'ExampleFlow',@Source,@Id,DATEADD(second,3,@T),DATEADD(second,3,@T),0,@Flow),
            (60,N'OnPostExecute',N'ExampleFlow',@Source,@Id,DATEADD(second,5,@T),DATEADD(second,5,@T),0,N'');
