mponentId], CONVERT(varbinary(max),[DestinationComponentName]) AS [DestinationComponentName], [InputId] AS [InputId], CONVERT(varbinary(max),[InputName]) AS [InputName], [EventCount] AS [EventCount], [RowsSentSum] AS [RowsSentSum], [MinRowsSent] AS [MinRowsSent], [MaxRowsSent] AS [MaxRowsSent], [FirstObservedTime] AS [FirstObservedTime], [LastObservedTime] AS [LastObservedTime], CONVERT(varbinary(max),[EvidenceLogIdsJson]) AS [EvidenceLogIdsJson], [SourceNameConflict] AS [SourceNameConflict], [PathNameConflict] AS [PathNameConflict], [DestinationNameConflict] AS [DestinationNameConflict], [InputNameConflict] AS [InputNameConflict], [InputIsTruncated] AS [InputIsTruncated], CONVERT(varbinary(max),[CoverageStatus]) AS [CoverageStatus], [OccurrenceStartTime] AS [OccurrenceStartTime], [OccurrenceEndTime] AS [OccurrenceEndTime], [ObservedExecutionDurationMs] AS [ObservedExecutionDurationMs], [ReportedTransferRowsPerSecond] AS [ReportedTransferRowsPerSecond], CONVERT(varbinary(max),[RateStatus]) AS [RateStatus], CONVERT(varbinary(max),[RateTimeBasis]) AS [RateTimeBasis], CONVERT(varbinary(max),[EvidenceLevel]) AS [EvidenceLevel], CONVERT(varbinary(max),[EvidenceSource]) AS [EvidenceSource] FROM #ExampleThroughputExpected)
