    DECLARE @Flags int=0,@Task bit,@Row bit,@Phase bit,@Life bit,@Lookup bit,@Written bit,@ExpectedVersion int;
    WHILE @Flags<128
    BEGIN
        SELECT @Task=IIF(@Flags&1=1,1,0),@Row=IIF(@Flags&2=2,1,0),@Phase=IIF(@Flags&4=4,1,0),@Life=IIF(@Flags&8=8,1,0),@Lookup=IIF(@Flags&16=16,1,0),@Written=IIF(@Flags&32=32,1,0),@Through=IIF(@Flags&64=64,1,0);
        EXEC [monitor].[USP_SsisLegacyLogAnalysis] @LoggingDatabase=@Db,@LoggingTable=N'ExampleThroughputLogSource',@ExecutionId=@Id,@HighImpactConfirmed=1,@IncludeTaskAnalysis=@Task,
            @IncludeRowFlowAnalysis=@Row,@IncludeComponentPhaseAnalysis=@Phase,@IncludeComponentLifecyclePhases=@Life,@IncludeLookupCacheAnalysis=@Lookup,@IncludeRowsWrittenAnalysis=@Written,@IncludeThroughputAnalysis=@Through,
            @ResultSetArt='NONE',@JsonErzeugen=1,@Json=@J OUTPUT,@PrintMeldungen=0,@StatusCodeOut=@Status OUTPUT;
        SET @ExpectedVersion=CASE WHEN @Through=1 THEN 8 WHEN @Written=1 THEN 7 WHEN @Lookup=1 THEN 6 WHEN @Phase=1 THEN IIF(@Life=1,5,4) WHEN @Row=1 THEN 3 WHEN @Task=1 THEN 2 ELSE 1 END;
        IF TRY_CONVERT(int,JSON_VALUE(@J,'$.meta.SchemaVersion'))<>@ExpectedVersion
            OR (@Through=0 AND JSON_QUERY(@J,'$.rowFlowThroughput') IS NOT NULL)
            OR (@Through=1 AND JSON_QUERY(@J,'$.rowFlowThroughput') IS NULL)
            OR (((@Life=1 AND @Phase=0) OR (@Through=1 AND @Row=0)) AND @Status<>'INVALID_PARAMETER')
            OR (NOT((@Life=1 AND @Phase=0) OR (@Through=1 AND @Row=0)) AND @Status='INVALID_PARAMETER') THROW 56906,N'T_FLAG_COMBINATIONS',1;
        SET @Flags+=1;
    END;
