       OR (SELECT COUNT(*) FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleThroughputExport'))<>33
       OR EXISTS(SELECT 1 FROM tempdb.sys.columns WHERE object_id=OBJECT_ID(N'tempdb..#ExampleThroughputExport') AND (is_identity=1 OR is_computed=1)) THROW 56908,N'T_TABLE_NATIVE_SCHEMA',1;
