    IF OBJECT_ID(N'dbo.ExampleThroughputLogSource')<>@TableId THROW 56892,N'T_TABLE_ID_CHANGED',1;
    DROP TABLE dbo.ExampleThroughputLogSource;SET @TableId=NULL;
    IF @@OPTIONS<>@OuterOptions OR @@LOCK_TIMEOUT<>@OuterLock OR @@TRANCOUNT<>@OuterTran THROW 56813,N'T_CALLER_CHANGED',1;
    SELECT N'PASS' AS ThroughputSyntheticStatus,24 AS MathAndContextCases,128 AS FlagCases,1 AS ExportCases,6 AS MappingCases,5 AS SourceCases,33 AS IndependentFields;
END TRY
BEGIN CATCH
    IF @Impersonated=1 REVERT;
    IF @UserId IS NOT NULL AND DATABASE_PRINCIPAL_ID(N'ExampleThroughputReader')=@UserId DROP USER ExampleThroughputReader;
    IF @TableId IS NOT NULL AND OBJECT_ID(N'dbo.ExampleThroughputLogSource')=@TableId DROP TABLE dbo.ExampleThroughputLogSource;
    THROW;
END CATCH;
GO
